#include <numeric>
#include <unordered_map>
#include <vector>
using namespace std;

class Solution {
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        int answer = 1;

        for (int i = 0; i < n && n - i > answer; ++i) {
            unordered_map<long long, int> counts;
            counts.reserve(n - i);

            for (int j = i + 1; j < n; ++j) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int g = gcd(dx, dy);
                dx /= g;
                dy /= g;

                // Give opposite directions the same representation.
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                // Normalized dy is in [-20000, 20000].
                long long key = 40001LL * dx + (dy + 20000);
                answer = max(answer, ++counts[key] + 1);
            }
        }

        return answer;
    }
};

